SELECT p.id, p.title, p.cover_image, p.content_text, p.like_count, p.comment_count, p.collect_count, p.created_at, u.id AS author_id, u.username AS author_username, u.nickname AS author_nickname, u.avatar AS author_avatar FROM post p JOIN user u ON p.user_id = u.id WHERE p.status = 1
AND (p.created_at < #{cursorTime} OR (p.created_at = #{cursorTime} AND p.id < #{cursorId}))
ORDER BY p.created_at DESC, p.id DESC LIMIT #{size}

SELECT p.id, p.title, p.cover_image, p.content_text, p.like_count, p.comment_count, p.collect_count, p.created_at, u.id AS author_id, u.username AS author_username, u.nickname AS author_nickname, u.avatar AS author_avatar FROM post p JOIN user u ON p.user_id = u.id WHERE p.status = 1
AND (p.like_count < #{cursorCount} OR (p.like_count = #{cursorCount} AND p.id < #{cursorId}))
ORDER BY p.like_count DESC, p.id DESC LIMIT #{size}
